#include <stdio.h>
#include <stdlib.h>

int main() {
    int n;
    scanf("%d", &n);

    int *a = (int *)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    int *visited = (int *)calloc(n, sizeof(int));
    int *in_cycle = (int *)calloc(n, sizeof(int));
    int *state = (int *)calloc(n, sizeof(int)); // 0 = unvisited, 1 = visiting, 2 = processed

    int result = 0;

    for (int i = 0; i < n; i++) {
        if (state[i] != 0) continue;

        // DFS to find cycle
        int cur = i;
        while (state[cur] == 0) {
            state[cur] = 1;
            cur = (cur + a[cur]) % n;
        }

        // If we found a node that is currently being visited, we have a cycle
        if (state[cur] == 1) {
            // Mark all nodes in the cycle
            int cycle_start = cur;
            do {
                in_cycle[cur] = 1;
                cur = (cur + a[cur]) % n;
            } while (cur != cycle_start);
        }

        // Mark all visited nodes as processed
        cur = i;
        while (state[cur] == 1) {
            state[cur] = 2;
            cur = (cur + a[cur]) % n;
        }
    }

    // Count nodes that can reach a cycle (which are exactly those in cycles)
    // Actually, starting from a node in a cycle will eventually return to start
    // Starting from a node that leads to a cycle but is not in the cycle will never return to start

    for (int i = 0; i < n; i++) {
        if (in_cycle[i]) result++;
    }

    printf("%d\n", result);

    free(a);
    free(visited);
    free(in_cycle);
    free(state);

    return 0;
}

