int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int *a = (int *)malloc(sizeof(int) * N);
    int *to = (int *)malloc(sizeof(int) * N);
    int *indeg = (int *)calloc(N, sizeof(int));
    int *removed = (int *)calloc(N, sizeof(int));
    int *queue = (int *)malloc(sizeof(int) * N);

    for (int i = 0; i < N; i++) {
        scanf("%d", &a[i]);
        long long step = a[i] % N;
        to[i] = (int)((i + step) % N);
        indeg[to[i]]++;
    }

    int head = 0, tail = 0;
    for (int i = 0; i < N; i++) {
        if (indeg[i] == 0) queue[tail++] = i;
    }

    while (head < tail) {
        int v = queue[head++];
        removed[v] = 1;
        int u = to[v];
        indeg[u]--;
        if (indeg[u] == 0) queue[tail++] = u;
    }

    int answer = 0;
    for (int i = 0; i < N; i++) {
        if (!removed[i]) answer++;
    }

    printf("%d\n", answer);

    free(a);
    free(to);
    free(indeg);
    free(removed);
    free(queue);
    return 0;
}

