public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        int[] A = new int[N];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            A[i] = Integer.parseInt(st.nextToken());
        }

        boolean[] visited = new boolean[N];
        boolean[] inStack = new boolean[N];
        int[] state = new int[N]; // 0 = unvisited, 1 = in current path, 2 = processed

        int count = 0;
        for (int i = 0; i < N; i++) {
            if (state[i] == 0) {
                if (dfs(i, A, state)) {
                    // Mark all nodes in this cycle as good
                    markCycle(i, A, state);
                }
            }
        }

        // Count nodes that are part of a cycle (state == 2 means in cycle)
        for (int i = 0; i < N; i++) {
            if (state[i] == 2) count++;
        }

        System.out.println(count);
    }

    // Returns true if a cycle is found from node u
    static boolean dfs(int u, int[] A, int[] state) {
        state[u] = 1; // visiting
        int v = (u + A[u]) % A.length;
        if (state[v] == 0) {
            if (dfs(v, A, state)) {
                return true;
            }
        } else if (state[v] == 1) {
            // Found a cycle
            return true;
        }
        state[u] = 2; // processed but not in cycle
        return false;
    }

    // Mark all nodes that are part of the cycle reachable from start
    static void markCycle(int start, int[] A, int[] state) {
        int slow = start;
        int fast = start;
        // Find meeting point
        do {
            slow = (slow + A[slow]) % A.length;
            fast = (fast + A[fast]) % A.length;
            fast = (fast + A[fast]) % A.length;
        } while (slow != fast);

        // Find cycle start
        slow = start;
        while (slow != fast) {
            slow = (slow + A[slow]) % A.length;
            fast = (fast + A[fast]) % A.length;
        }

        // Mark all nodes in cycle
        int cycleStart = slow;
        do {
            state[slow] = 2;
            slow = (slow + A[slow]) % A.length;
        } while (slow != cycleStart);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        int[] a = new int[N];
        for (int i = 0; i < N; i++) a[i] = fs.nextInt();

        // f(i) = (i + a[i]) mod N
        // A starting square can reach itself again iff it belongs to a directed cycle.
        // Since every node has outdegree 1, the answer is the total number of nodes
        // contained in all directed cycles.

        int[] indeg = new int[N];
        int[] to = new int[N];
        for (int i = 0; i < N; i++) {
            int nxt = (int)(((long)i + a[i]) % N);
            to[i] = nxt;
            indeg[nxt]++;
        }

        ArrayDeque<Integer> q = new ArrayDeque<>();
        boolean[] removed = new boolean[N];

        for (int i = 0; i < N; i++) {
            if (indeg[i] == 0) q.add(i);
        }

        while (!q.isEmpty()) {
            int v = q.poll();
            removed[v] = true;
            int u = to[v];
            indeg[u]--;
            if (indeg[u] == 0) q.add(u);
        }

        int ans = 0;
        for (int i = 0; i < N; i++) {
            if (!removed[i]) ans++;
        }

        System.out.println(ans);
    }
}

