using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> A(N);
    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }

    // We'll use union-find to detect cycles in the functional graph
    vector<int> parent(N);
    iota(parent.begin(), parent.end(), 0);
    vector<int> size(N, 1);

    function<int(int)> find = [&](int x) -> int {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    auto unite = [&](int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (size[a] < size[b]) swap(a, b);
        parent[b] = a;
        size[a] += size[b];
    };

    // Connect each node to its next node (A[i] steps clockwise)
    for (int i = 0; i < N; i++) {
        int next = (i + A[i]) % N;
        unite(i, next);
    }

    // Count nodes that belong to cycles of size 1 or more
    // A node belongs to a cycle if its next node is in the same component
    // and the component size equals the number of nodes that can reach each other.
    // More directly: count nodes that are part of any cycle.
    // We can detect cycles by checking if find(i) == find((i + A[i]) % N) 
    // and then traversing the cycle.

    vector<bool> in_cycle(N, false);
    vector<int> visited(N, 0); // 0=unvisited, 1=visiting, 2=processed

    function<void(int)> dfs = [&](int u) {
        visited[u] = 1;
        int v = (u + A[u]) % N;
        if (visited[v] == 1) {
            // Found a cycle, mark all nodes in it
            int cur = v;
            do {
                in_cycle[cur] = true;
                cur = (cur + A[cur]) % N;
            } while (cur != v);
        } else if (visited[v] == 0) {
            dfs(v);
        }
        visited[u] = 2;
    };

    for (int i = 0; i < N; i++) {
        if (visited[i] == 0) {
            dfs(i);
        }
    }

    int ans = 0;
    for (bool b : in_cycle) {
        if (b) ans++;
    }
    cout << ans << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    while (cin >> n && n != 0) {
        vector<int> a(n);
        for (int i = 0; i < n; i++) cin >> a[i];

        // next[i] = (i + a[i]) % n
        vector<int> nxt(n);
        for (int i = 0; i < n; i++) nxt[i] = (i + a[i]) % n;

        // Find all nodes on cycles
        vector<int> state(n, 0); // 0=unvisited, 1=in path, 2=done, 3=on cycle
        vector<int> order; // track path order
        vector<int> pos(n, -1); // position in current path

        int ans = 0;

        for (int start = 0; start < n; start++) {
            if (state[start] != 0) continue;

            order.clear();
            int cur = start;

            while (state[cur] == 0) {
                state[cur] = 1;
                pos[cur] = order.size();
                order.push_back(cur);
                cur = nxt[cur];
            }

            if (state[cur] == 1) {
                // cur is on the cycle, mark all cycle nodes
                int cycle_start_pos = pos[cur];
                for (int i = cycle_start_pos; i < (int)order.size(); i++) {
                    state[order[i]] = 3;
                    ans++;
                }
                // mark tail nodes as done
                for (int i = 0; i < cycle_start_pos; i++) {
                    state[order[i]] = 2;
                }
            } else {
                // cur is already processed (state 2 or 3), just mark all as done
                for (int node : order) {
                    state[node] = 2;
                }
            }
        }

        cout << ans << endl;
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> a(N);
    for (int i = 0; i < N; ++i) cin >> a[i];

    // Functional graph:
    // next(i) = (i + a[i]) mod N
    // A starting square i can "finish" iff repeated moves return to i,
    // i.e. i belongs to a directed cycle.
    vector<int> indeg(N, 0), nxt(N);
    for (int i = 0; i < N; ++i) {
        nxt[i] = (int)((i + a[i]) % N);
        indeg[nxt[i]]++;
    }

    queue<int> q;
    vector<int> removed(N, 0);

    // Remove all nodes that cannot be in any cycle by topological pruning.
    for (int i = 0; i < N; ++i) {
        if (indeg[i] == 0) q.push(i);
    }

    while (!q.empty()) {
        int v = q.front();
        q.pop();
        removed[v] = 1;
        int to = nxt[v];
        if (--indeg[to] == 0) q.push(to);
    }

    int ans = 0;
    for (int i = 0; i < N; ++i) {
        if (!removed[i]) ans++;
    }

    cout << ans << '\n';
    return 0;
}
